<?php

namespace MongoDB\Driver;

use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-bulkwrite" class="reference"> <h1 class="title">The MongoDB\Driver\BulkWrite class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-driver-bulkwrite.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\BulkWrite</strong></span> collects one or more    write operations that should be sent to the server. After adding any    number of insert, update, and delete operations, the collection may be    executed via    <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()}</span>.   </p>   <p class="simpara">    Write operations may either be ordered (default) or unordered. Ordered write    operations are sent to the server, in the order provided, for serial    execution. If a write fails, any remaining operations will be aborted.    Unordered operations are sent to the server in an arbitrary order    where they may be executed in parallel. Any errors that occur are reported    after all operations have been attempted.   </p>  </div>  <div class="section" id="mongodb-driver-bulkwrite.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\BulkWrite</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.countable.php" class="interfacename">Countable</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-bulkwrite.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-bulkwrite.count.php" class="methodname" style="color:#CC7832">count</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-bulkwrite.delete.php" class="methodname" style="color:#CC7832">delete</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$deleteOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-bulkwrite.insert.php" class="methodname" style="color:#CC7832">insert</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-bulkwrite.update.php" class="methodname" style="color:#CC7832">update</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$newObj</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$updateOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>   }</div>  </div>  <div class="section" id="mongodb-driver-bulkwrite.examples">   <h2 class="title">示例</h2>   <div class="example" id="example-1">    <p><strong>示例 #1 Mixed write operations are grouped by type</strong></p>    <div class="example-contents"><p>     Mixed write operations (i.e. inserts, updates, and deletes) will be     assembled into typed write commands to be sent sequentially to the server.    </p></div>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">([</span><span style="color: #DD0000">'ordered' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>     Will result in four write commands (i.e. roundtrips) being executed. Since     the operations are ordered, the third insertion cannot be sent until the     preceding update is executed.    </p></div>   </div>   <div class="example" id="example-2">    <p><strong>示例 #2 Ordered write operations causing an error</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">([</span><span style="color: #DD0000">'ordered' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #DD0000">'hello' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'world'</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'hello' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'earth'</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #DD0000">'hello' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'pluto'</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'hello' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'moon'</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">5</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$writeConcern </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">::</span><span style="color: #9876AA">MAJORITY</span><span style="color: #007700">, </span><span style="color: #9876AA">1000</span><span style="color: #007700">);<br><br>try {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">, [</span><span style="color: #DD0000">'writeConcern' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$writeConcern</span><span style="color: #007700">]);<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\BulkWriteException \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteResult</span><span style="color: #007700">();<br><br>    </span><span style="color: #FF8000">// Check if the write concern could not be fulfilled<br>    </span><span style="color: #007700">if (</span><span style="color: #9876AA">\$writeConcernError </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcernError</span><span style="color: #007700">()) {<br>        </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"%s (%d): %s\n"</span><span style="color: #007700">,<br>            </span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCode</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">var_export</span><span style="color: #007700">(</span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getInfo</span><span style="color: #007700">(), </span><span style="color: #9876AA">true</span><span style="color: #007700">)<br>        );<br>    }<br><br>    </span><span style="color: #FF8000">// Check if any write operations did not complete at all<br>    </span><span style="color: #007700">foreach (</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteErrors</span><span style="color: #007700">() as </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">) {<br>        </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Operation#%d: %s (%d)\n"</span><span style="color: #007700">,<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getIndex</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCode</span><span style="color: #007700">()<br>        );<br>    }<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\Exception \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Other error: %s\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">());<br>    exit;<br>}<br><br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Inserted %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getInsertedCount</span><span style="color: #007700">());<br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Updated  %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModifiedCount</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   <p class="simpara">以上示例会输出：</p>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>Operation#7:&nbsp;E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;index:&nbsp;db.collection.\$_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;3&nbsp;}&nbsp;(11000)<br>Inserted&nbsp;4&nbsp;document(s)<br>Updated&nbsp;&nbsp;2&nbsp;document(s)<br></blockquote></div>   </div>   <p class="simpara">    If the write concern could not be fulfilled, the example above would output    something like:   </p>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>waiting&nbsp;for&nbsp;replication&nbsp;timed&nbsp;out&nbsp;(64):&nbsp;array&nbsp;(<br>&nbsp;&nbsp;'wtimeout'&nbsp;=&gt;&nbsp;true,<br>)<br>Operation#7:&nbsp;E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;index:&nbsp;databaseName.collectionName.\$_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;3&nbsp;}&nbsp;(11000)<br>Inserted&nbsp;4&nbsp;document(s)<br>Updated&nbsp;&nbsp;2&nbsp;document(s)<br></blockquote></div>   </div>   <p class="simpara">    If we execute the example above, but allow for unordered writes:   </p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">([</span><span style="color: #DD0000">'ordered' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">]);<br></span><span style="color: #FF8000">// ... <br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <p class="simpara">以上示例会输出：</p>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>Operation#7:&nbsp;E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;index:&nbsp;db.collection.\$_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;3&nbsp;}&nbsp;(11000)<br>Operation#8:&nbsp;E11000&nbsp;duplicate&nbsp;key&nbsp;error&nbsp;index:&nbsp;db.collection.\$_id_&nbsp;dup&nbsp;key:&nbsp;{&nbsp;:&nbsp;4&nbsp;}&nbsp;(11000)<br>Inserted&nbsp;5&nbsp;document(s)<br>Updated&nbsp;&nbsp;2&nbsp;document(s)<br></blockquote></div>   </div>  </div>  <div class="section" id="mongodb-driver-bulkwrite.seealso">   <h2 class="title">参见</h2>   <ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()}</span></li>    <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php" class="classname">MongoDB\Driver\WriteResult</a></span></li>    <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></li>    <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcernerror.php" class="classname">MongoDB\Driver\WriteConcernError</a></span></li>    <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeerror.php" class="classname">MongoDB\Driver\WriteError</a></span></li>   </ul>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\BulkWrite::__construct} — Create a new BulkWrite</li><li>{@link MongoDB\Driver\BulkWrite::count} — Count number of write operations in the bulk</li><li>{@link MongoDB\Driver\BulkWrite::delete} — Add a delete operation to the bulk</li><li>{@link MongoDB\Driver\BulkWrite::insert} — Add an insert operation to the bulk</li><li>{@link MongoDB\Driver\BulkWrite::update} — Add an update operation to the bulk</li></ul></div>
 * 
 * The BulkWrite collects one or more write operations that should be sent to the server.
 * After adding any number of insert, update, and delete operations, the collection may be executed via Manager::executeBulkWrite().
 * Write operations may either be ordered (default) or unordered.
 * Ordered write operations are sent to the server, in the order provided, for serial execution.
 * If a write fails, any remaining operations will be aborted.
 * Unordered operations are sent to the server in an arbitrary order where they may be executed in parallel.
 * Any errors that occur are reported after all operations have been attempted.
 */
final class BulkWrite implements \Countable
{
    /**
 * <div id="mongodb-driver-bulkwrite.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWrite::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWrite::__construct</span> — <span class="dc-title">Create a new BulkWrite</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwrite.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWrite::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>  <p class="simpara">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>, which is a   mutable object to which one or more write operations may be added. The   write(s) may then be executed with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()}</span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwrite.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">options</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>          <th>Default</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>bypassDocumentValidation</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           <span class="simpara">            If <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>, allows insert and update operations to circumvent            document level validation.           </span>           <span class="simpara">            This option is available in MongoDB 3.2+ and is ignored for older            server versions, which do not support document level validation.           </span>          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>         <tr>          <td>comment</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></td>          <td>           <span class="simpara">            An arbitrary comment to help trace the operation through the            database profiler, currentOp output, and logs.           </span>           <span class="simpara">            This option is available in MongoDB 4.4+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>                  <tr>          <td>let</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            Map of parameter names and values. Values must be constant or closed expressions that do not reference document fields. Parameters can then be accessed as variables in an aggregate expression context (e.g. <span class="literal">\$\$var</span>).           </span>           <span class="simpara">            This option is available in MongoDB 5.0+ and will result in an exception at execution time if specified for an older server version.           </span>          </td>         </tr>         <tr>          <td>ordered</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           Ordered operations (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>) are executed serially on the MongoDB           server, while unordered operations (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>) are sent to the server           in an arbitrary order and may be executed in parallel.          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong></td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwrite.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-bulkwrite.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.14.0</td>      <td>       Added the <span class="literal">"comment"</span> and <span class="literal">"let"</span>       options.      </td>     </tr>     <tr>      <td>PECL mongodb 1.1.0</td>      <td>       Added the <span class="literal">"bypassDocumentValidation"</span> option.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwrite.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-3">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWrite::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">([</span><span style="color: #DD0000">'ordered' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">(<br>    [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">],<br>    [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]],<br>    [</span><span style="color: #DD0000">'limit' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'upsert' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">]<br>);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">], [</span><span style="color: #DD0000">'limit' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">(<br>    [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">],<br>    [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]],<br>    [</span><span style="color: #DD0000">'limit' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'upsert' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true</span><span style="color: #007700">]<br>);<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$writeConcern </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\WriteConcern</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">);<br><br>try {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">, [</span><span style="color: #DD0000">'writeConcern' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$writeConcern</span><span style="color: #007700">]);<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\BulkWriteException \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteResult</span><span style="color: #007700">();<br><br>    </span><span style="color: #FF8000">// Check if the write concern could not be fulfilled<br>    </span><span style="color: #007700">if (</span><span style="color: #9876AA">\$writeConcernError </span><span style="color: #007700">= </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteConcernError</span><span style="color: #007700">()) {<br>        </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"%s (%d): %s\n"</span><span style="color: #007700">,<br>            </span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCode</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">var_export</span><span style="color: #007700">(</span><span style="color: #9876AA">\$writeConcernError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getInfo</span><span style="color: #007700">(), </span><span style="color: #9876AA">true</span><span style="color: #007700">)<br>        );<br>    }<br><br>    </span><span style="color: #FF8000">// Check if any write operations did not complete at all<br>    </span><span style="color: #007700">foreach (</span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getWriteErrors</span><span style="color: #007700">() as </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">) {<br>        </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Operation#%d: %s (%d)\n"</span><span style="color: #007700">,<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getIndex</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(),<br>            </span><span style="color: #9876AA">\$writeError</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCode</span><span style="color: #007700">()<br>        );<br>    }<br>} catch (</span><span style="color: #9876AA">MongoDB\Driver\Exception\Exception \$e</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Other error: %s\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">());<br>    exit;<br>}<br><br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Inserted %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getInsertedCount</span><span style="color: #007700">());<br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Updated  %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getModifiedCount</span><span style="color: #007700">());<br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Upserted %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getUpsertedCount</span><span style="color: #007700">());<br></span><span style="color: #9876AA">printf</span><span style="color: #007700">(</span><span style="color: #DD0000">"Deleted  %d document(s)\n"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$result</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getDeletedCount</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">Inserted&nbsp;2&nbsp;document(s)<br>Updated&nbsp;&nbsp;1&nbsp;document(s)<br>Upserted&nbsp;1&nbsp;document(s)<br>Deleted&nbsp;&nbsp;1&nbsp;document(s)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-bulkwrite.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()} - Execute one or more write operations</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php" class="classname">MongoDB\Driver\WriteResult</a></span></li>  </ul> </div></div>
 * 
     * Create a new BulkWrite
     * Constructs a new ordered (default) or unordered BulkWrite.
     * @link https://php.net/manual/zh/mongodb-driver-bulkwrite.construct.php
     * @param array $options
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function __construct(?array $options = null) {}


    final public function __wakeup() {}

    /**
 * <div id="mongodb-driver-bulkwrite.count" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWrite::count</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWrite::count</span> — <span class="dc-title">Count number of write operations in the bulk</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwrite.count-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWrite::count</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></div>  <p class="simpara">   Returns the number of write operations added to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwrite.count-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwrite.count-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns number of write operations added to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span> object.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwrite.count-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-bulkwrite.count-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.2.0</td>      <td>       Returns the number of write operations added to the       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span> object. Earlier versions       returned the expected number of client-to-server roundtrips required to       execute all write operations.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwrite.count-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWrite::count()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">([</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">], [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">count</span><span style="color: #007700">(</span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(4)</blockquote></div>   </div>  </div> </div></div>
 * 
     * Count expected roundtrips for executing the bulk
     * Returns the expected number of client-to-server roundtrips required to execute all write operations in the BulkWrite.
     * @link https://php.net/manual/zh/mongodb-driver-bulkwrite.count.php
     * @return int number of expected roundtrips to execute the BulkWrite.
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function count(): int {}

    /**
 * <div id="mongodb-driver-bulkwrite.delete" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWrite::delete</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWrite::delete</span> — <span class="dc-title">Add a delete operation to the bulk</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwrite.delete-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWrite::delete</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$deleteOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Adds a delete operation to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwrite.delete-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">filter</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/tutorial/query-documents/" class="link external">»&nbsp;query predicate</a>.      An empty predicate will match all documents in the collection.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       When evaluating query criteria, MongoDB compares types and values according to its own <a href="https://www.mongodb.com/docs/manual/reference/bson-type-comparison-order/" class="link external">»&nbsp;comparison rules for BSON types</a>, which differs from PHP's <a href="https://php.net/manual/zh/types.comparisons.php" class="link">comparison</a> and <a href="https://php.net/manual/zh/language.types.type-juggling.php" class="link">type juggling</a> rules. When matching a special BSON type the query criteria should use the respective <a href="https://php.net/manual/zh/mongodb.bson.php" class="link">BSON class</a> (e.g. use <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> to match an <a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId</a>).      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">deleteOptions</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>deleteOptions</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>          <th>Default</th>         </tr>        </thead>        <tbody class="tbody">                  <tr>          <td>collation</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            <a href="https://www.mongodb.com/docs/upcoming/reference/collation/" class="link external">»&nbsp;Collation</a> allows users to specify language-specific rules for string comparison, such as rules for lettercase and accent marks. When specifying collation, the <span class="literal">"locale"</span> field is mandatory; all other collation fields are optional. For descriptions of the fields, see <a href="https://www.mongodb.com/docs/upcoming/reference/collation/#collation-document" class="link external">»&nbsp;Collation Document</a>.           </span>           <span class="simpara">            If the collation is unspecified but the collection has a default collation, the operation uses the collation specified for the collection. If no collation is specified for the collection or for the operation, MongoDB uses the simple binary comparison used in prior versions for string comparisons.           </span>           <span class="simpara">            This option is available in MongoDB 3.4+ and will result in an exception at execution time if specified for an older server version.           </span>          </td>         </tr>         <tr>          <td>hint</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            Index specification. Specify either the index name as a string or            the index key pattern. If specified, then the query system will only            consider plans using the hinted index.           </span>           <span class="simpara">            This option is available in MongoDB 4.4+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>         <tr>          <td>limit</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>Delete all matching documents (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>), or only the first matching document (<strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>)</td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwrite.delete-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwrite.delete-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-bulkwrite.delete-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.8.0</td>      <td>       Added the <span class="literal">"hint"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.2.0</td>      <td>       Added the <span class="literal">"collation"</span> option.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwrite.delete-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWrite::delete()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">], [</span><span style="color: #DD0000">'limit' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]);<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">delete</span><span style="color: #007700">([</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">], [</span><span style="color: #DD0000">'limit' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">0</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-bulkwrite.delete-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()} - Execute one or more write operations</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php" class="classname">MongoDB\Driver\WriteResult</a></span></li>  </ul> </div></div>
 * 
     * Add a delete operation to the bulk
     * @link https://php.net/manual/zh/mongodb-driver-bulkwrite.delete.php
     * @param array|object $filter The search filter
     * @param array|null $deleteOptions
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function delete(array|object $filter, ?array $deleteOptions = null): void {}

    /**
 * <div id="mongodb-driver-bulkwrite.insert" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWrite::insert</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWrite::insert</span> — <span class="dc-title">Add an insert operation to the bulk</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwrite.insert-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWrite::insert</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="simpara">   Adds an insert operation to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwrite.insert-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">document</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      A document to insert.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwrite.insert-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the <span class="literal">_id</span> of the inserted document. If the   <span class="parameter" style="color:#3A95FF">document</span> did not have an <span class="literal">_id</span>, the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> generated for the insert will   be returned.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwrite.insert-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-bulkwrite.insert-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.3.0</td>      <td>       The <span class="literal">_id</span> of the inserted document is always returned.       Previously, the method only returned a value if a       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> was generated.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwrite.insert-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWrite::insert()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$doc1 </span><span style="color: #007700">= [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$doc2 </span><span style="color: #007700">= [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'custom-id'</span><span style="color: #007700">, </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$doc3 </span><span style="color: #007700">= [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'0123456789abcdef01234567'</span><span style="color: #007700">), </span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">];<br><br></span><span style="color: #9876AA">\$id1 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">\$doc1</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$id2 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">\$doc2</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$id3 </span><span style="color: #007700">= </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">insert</span><span style="color: #007700">(</span><span style="color: #9876AA">\$doc3</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$id1</span><span style="color: #007700">, </span><span style="color: #9876AA">\$id2</span><span style="color: #007700">, </span><span style="color: #9876AA">\$id3</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(MongoDB\BSON\ObjectId)#3&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"67f58058d1a0aa2fd80d55d0"<br>}<br>string(9)&nbsp;"custom-id"<br>object(MongoDB\BSON\ObjectId)#4&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"0123456789abcdef01234567"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-bulkwrite.insert-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()} - Execute one or more write operations</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php" class="classname">MongoDB\Driver\WriteResult</a></span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-persistable.php" class="interfacename">MongoDB\BSON\Persistable</a></span></li>  </ul> </div></div>
 * 
     * Add an insert operation to the bulk
     * @link https://php.net/manual/zh/mongodb-driver-bulkwrite.insert.php
     * @return mixed If the document did not have an _id, a MongoDB\BSON\ObjectId will be generated and returned; otherwise, no value is returned.
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function insert(array|object $document) {}

    /**
 * <div id="mongodb-driver-bulkwrite.update" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\BulkWrite::update</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\BulkWrite::update</span> — <span class="dc-title">Add an update operation to the bulk</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-bulkwrite.update-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\BulkWrite::update</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$filter</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$newObj</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$updateOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div>  <p class="simpara">   Adds an update operation to the   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-bulkwrite.php" class="classname">MongoDB\Driver\BulkWrite</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-bulkwrite.update-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">filter</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      The <a href="https://www.mongodb.com/docs/manual/tutorial/query-documents/" class="link external">»&nbsp;query predicate</a>.      An empty predicate will match all documents in the collection.     </span>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       When evaluating query criteria, MongoDB compares types and values according to its own <a href="https://www.mongodb.com/docs/manual/reference/bson-type-comparison-order/" class="link external">»&nbsp;comparison rules for BSON types</a>, which differs from PHP's <a href="https://php.net/manual/zh/types.comparisons.php" class="link">comparison</a> and <a href="https://php.net/manual/zh/language.types.type-juggling.php" class="link">type juggling</a> rules. When matching a special BSON type the query criteria should use the respective <a href="https://php.net/manual/zh/mongodb.bson.php" class="link">BSON class</a> (e.g. use <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> to match an <a href="https://www.mongodb.com/docs/manual/reference/bson-types/#objectid" class="link external">»&nbsp;ObjectId</a>).      </span>     </p></blockquote>    </dd>          <dt><span class="parameter" style="color:#3A95FF">newObj</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>)</dt>    <dd>     <span class="simpara">      A document containing either update operators (e.g.      <span class="literal">\$set</span>), a replacement document (i.e.      <em>only</em> <span class="literal">field:value</span> expressions), or      an <a href="https://www.mongodb.com/docs/manual/reference/command/update/#update-with-an-aggregation-pipeline" class="link external">»&nbsp;aggregation pipeline</a>.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">updateOptions</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>updateOptions</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>          <th>Default</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>arrayFilters</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></td>          <td>           <span class="simpara">            An array of filter documents that determines which array elements to            modify for an update operation on an array field. See            <a href="https://www.mongodb.com/docs/manual/reference/command/update/#update-command-arrayfilters" class="link external">»&nbsp;Specify arrayFilters for Array Update Operations</a>            in the MongoDB manual for more information.           </span>           <span class="simpara">            This option is available in MongoDB 3.6+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>                  <tr>          <td>collation</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            <a href="https://www.mongodb.com/docs/upcoming/reference/collation/" class="link external">»&nbsp;Collation</a> allows users to specify language-specific rules for string comparison, such as rules for lettercase and accent marks. When specifying collation, the <span class="literal">"locale"</span> field is mandatory; all other collation fields are optional. For descriptions of the fields, see <a href="https://www.mongodb.com/docs/upcoming/reference/collation/#collation-document" class="link external">»&nbsp;Collation Document</a>.           </span>           <span class="simpara">            If the collation is unspecified but the collection has a default collation, the operation uses the collation specified for the collection. If no collation is specified for the collection or for the operation, MongoDB uses the simple binary comparison used in prior versions for string comparisons.           </span>           <span class="simpara">            This option is available in MongoDB 3.4+ and will result in an exception at execution time if specified for an older server version.           </span>          </td>         </tr>         <tr>          <td>hint</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            Index specification. Specify either the index name as a string or            the index key pattern. If specified, then the query system will only            consider plans using the hinted index.           </span>           <span class="simpara">            This option is available in MongoDB 4.2+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>         <tr>          <td>multi</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           Update only the first matching document if <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>, or all           matching documents <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>. This option cannot be <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if           <span class="parameter" style="color:#3A95FF">newObj</span> is a replacement document.          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>         <tr>          <td>sort</td>          <td><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></td>          <td>           <span class="simpara">            Specify which document the operation updates if the query matches            multiple documents. The first document matched by the sort order            will be updated.           </span>           <span class="simpara">            This option cannot be used if <span class="literal">"multi"</span> is <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>.           </span>           <span class="simpara">            This option is available in MongoDB 8.0+ and will result in an            exception at execution time if specified for an older server            version.           </span>          </td>         </tr>         <tr>          <td>upsert</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></td>          <td>           If <span class="parameter" style="color:#3A95FF">filter</span> does not match an existing document,           insert a <em>single</em> document. The document will be           created from <span class="parameter" style="color:#3A95FF">newObj</span> if it is a replacement           document (i.e. no update operators); otherwise, the operators in           <span class="parameter" style="color:#3A95FF">newObj</span> will be applied to           <span class="parameter" style="color:#3A95FF">filter</span> to create the new document.          </td>          <td><strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong></td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-bulkwrite.update-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   没有返回值。  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-bulkwrite.update-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-bulkwrite.update-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.21.0</td>      <td>       Added the <span class="literal">"sort"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.7.0</td>      <td>       Added the <span class="literal">"hint"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.6.0</td>      <td>       The <span class="parameter" style="color:#3A95FF">newObj</span> parameter now accepts an aggregation       pipeline. This feature requires MongoDB 4.2+ and will result in an       exception at execution time if specified for an older server version.      </td>     </tr>     <tr>      <td>PECL mongodb 1.5.0</td>      <td>       Using the <span class="literal">"arrayFilters"</span> option will result in an       exception at execution time if unsupported by the server. Previously,       no exception would be thrown and the option may have been ignored.      </td>     </tr>     <tr>      <td>PECL mongodb 1.4.0</td>      <td>       Added the <span class="literal">"arrayFilters"</span> option.      </td>     </tr>     <tr>      <td>PECL mongodb 1.2.0</td>      <td>       Added the <span class="literal">"collation"</span> option.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-bulkwrite.update-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\BulkWrite::update()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$bulk </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\BulkWrite</span><span style="color: #007700">;<br></span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">update</span><span style="color: #007700">(<br>    [</span><span style="color: #DD0000">'x' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">],<br>    [</span><span style="color: #DD0000">'\$set' </span><span style="color: #007700">=&gt; [</span><span style="color: #DD0000">'y' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]],<br>    [</span><span style="color: #DD0000">'multi' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">, </span><span style="color: #DD0000">'upsert' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">]<br>);<br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeBulkWrite</span><span style="color: #007700">(</span><span style="color: #DD0000">'db.collection'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$bulk</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-bulkwrite.update-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeBulkWrite()} - Execute one or more write operations</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeresult.php" class="classname">MongoDB\Driver\WriteResult</a></span></li>  </ul> </div></div>
 * 
     * Add an update operation to the bulk
     * @link https://php.net/manual/zh/mongodb-driver-bulkwrite.update.php
     * @param array|object $filter The search filter
     * @param array|object $newObj A document containing either update operators (e.g. $set) or a replacement document (i.e. only field:value expressions)
     * @param array|null $updateOptions
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function update(array|object $filter, array|object $newObj, ?array $updateOptions = null) {}
}
